data:
{
 "CTT-GEN-01": {
  "title": "Register before you build",
  "status": "Active",
  "text": "Ask a CTT admin for your tag and lab range before you create anything. Objects without a registered tag cannot be traced back to an owner."
 },
 "CTT-GEN-02": {
  "title": "Announce disruptive work",
  "status": "Proposed",
  "text": "Post in the team channel before you do something others will notice: large ingestion tests, tenant-wide content changes, agent upgrades, isolating endpoints, or anything that floods the issues and cases tables."
 },
 "CTT-GEN-03": {
  "title": "No real customer data or secrets",
  "status": "Proposed",
  "text": "Use sample, synthetic or anonymised data. Don't store customer logs, credentials or personal data in the tenant, its lists or its knowledge sources."
 },
 "CTT-TAG-01": {
  "title": "Prefix object names with your tag",
  "status": "Active",
  "text": "Start the name of every object you create with `<tag> - `, for example `jvanhecke - Phishing triage`. This applies to: - Playbooks, scripts, jobs, lists - Dashboards, widgets, reports and report templates, saved XQL queries (query library) - Correlation rules, BIOCs, scheduled queries - Endpoint profiles and policy rules (prevention, extensions, agent settings, XDR collectors) - FIM rule groups, host firewall rule groups, device control profiles - Cloud workload and posture rules - Endpoint groups, asset groups, saved views and filters - Integration instances, engines, Broker VMs, agent installation packages - AI agents and AI actions you build Names that cannot hold spaces use `<tag>_<name>` instead: scripts (`jvanhecke_GetLabUsers`), lookup tables and other datasets (`jvanhecke_lab_assets`, lower case)."
 },
 "CTT-TAG-02": {
  "title": "Set your tag on objects that have a tag field",
  "status": "Active",
  "text": "Where an object has a tag or label field, add your tag to it. This applies to: - Playbooks (the playbook *Tags* field) - Endpoint policies and vulnerability policies - Case and issue layout rules - Automation rules (triggers)"
 },
 "CTT-TAG-03": {
  "title": "Tag custom parsing rules, modeling rules and list entries in a comment",
  "status": "Active",
  "text": "Rules and list entries have no name of their own on the tenant, so mark them in a comment: - Parsing and modeling rules: a comment line `// <tag>: <what this rule is for>` above your rule block. - Lists, including entries you add to built-in lists: put your tag in the list description, or in a comment next to each entry you add."
 },
 "CTT-TAG-04": {
  "title": "Use only your own tags",
  "status": "Active",
  "text": "Never create objects with a tag that is not yours in the registry. Use `CTT` only if you are a CTT admin building central content."
 },
 "CTT-OWN-01": {
  "title": "Don't change other people's objects",
  "status": "Active",
  "text": "Don't edit, rename, disable or delete an object whose tag belongs to someone else. Ask the owner (look them up in the registry, or ask the CTT Assistant), or duplicate the object under your own tag."
 },
 "CTT-OOTB-01": {
  "title": "Don't edit built-in content; duplicate it",
  "status": "Active",
  "text": "Built-in (out-of-the-box) and marketplace content is shared by everyone, and pack updates overwrite it. This includes playbooks, scripts, correlation rules, dashboards, layouts, BIOCs and analytics rules. To customise one, duplicate it, give the copy your tag (`CTT-TAG-01`), and change the copy. Don't detach or adopt marketplace playbooks."
 },
 "CTT-OOTB-02": {
  "title": "Don't edit built-in AI agents",
  "status": "Active",
  "text": "Leave the Palo Alto Networks agents (Case Investigation, Threat Intel, IT, \u2026) as they are. Build your own agent with your tag in its name."
 },
 "CTT-CEN-01": {
  "title": "Leave centrally managed areas to the CTT admins",
  "status": "Active",
  "text": "Only CTT admins change these: - CIE - The VirusTotal integration - Tenant settings (Settings > Configurations) - The marketplace: installing, updating and uninstalling content packs - SSO, RBAC, roles, user groups and permission testing - The Slack bot integration - XTI and TIM rules - Central content (anything named or tagged `CTT`) Need a pack installed or a setting changed? Ask in the team channel."
 },
 "CTT-CEN-02": {
  "title": "Create API keys with an expiry date and your tag",
  "status": "Proposed",
  "text": "Give every API key you create an expiration date, the lowest role that works, and your tag in its comment. Delete it when you are done."
 },
 "CTT-LAB-01": {
  "title": "Build your lab in your own IP range",
  "status": "Active",
  "text": "Put the machines, broker VMs and collectors of your lab in `10.<x>.0.0/16`, where `x` is your `lab_octet` in the registry. Never use another DC's range."
 },
 "CTT-LAB-02": {
  "title": "Tag your endpoints",
  "status": "Proposed",
  "text": "Add your tag as an endpoint tag on every agent you install, so endpoints, policies and cases can be traced to you. Scope your policies to your own endpoints (`CTT-TAG-02`)."
 },
 "CTT-LAB-03": {
  "title": "Remove what you no longer use",
  "status": "Proposed",
  "text": "Uninstall agents, delete broker VMs and engines, and disable collectors once a lab is finished."
 },
 "CTT-CASE-01": {
  "title": "Close Security Testing cases when your attack chain is done",
  "status": "Active",
  "text": "When you finish a test or demo attack chain, resolve its cases with the resolution reason *Security Testing*. Open test cases bury everyone else's demos."
 },
 "CTT-CASE-02": {
  "title": "Assign your test cases to yourself",
  "status": "Proposed",
  "text": "While you are testing, assign the cases your lab creates to yourself so others can see who is working on them."
 },
 "CTT-LIFE-01": {
  "title": "Clean up after yourself",
  "status": "Proposed",
  "text": "Delete objects you no longer need. Objects untouched for 90 days may be flagged for review."
 },
 "CTT-LIFE-02": {
  "title": "Hand over when you leave",
  "status": "Proposed",
  "text": "Before you leave the team, delete your objects or hand them over to another DC, who re-tags them."
 }
}
